<?php
declare(strict_types=1);
require_once __DIR__ . '/admin-layout.php';
require_once __DIR__ . '/../models/Booking.php';
$booking=new Booking(); $status=strtoupper(trim($_GET['status']??'')); $search=trim($_GET['search']??''); $rows=$booking->getAll($status,$search);
adminHeader('Bookings','Review and manage every booking request.');
?><div class="section-card"><div class="section-head"><div><h2>All Bookings</h2><p><?=number_format(count($rows))?> result(s)</p></div><form class="toolbar" method="get"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Search booking, name, mobile or route"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['NEW','CONFIRMED','IN_PROGRESS','COMPLETED','CANCELLED'] as $s): ?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=e(str_replace('_',' ',$s))?></option><?php endforeach;?></select><button class="btn-admin btn-primary" type="submit"><i class="ri-search-line"></i> Search</button><?php if($search||$status): ?><a class="btn-admin btn-light" href="bookings.php">Clear</a><?php endif;?></form></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Booking</th><th>Customer</th><th>Route</th><th>Travel Date</th><th>Trip</th><th>Visitors</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8"><div class="empty-state">No bookings match your search.</div></td></tr><?php else: foreach($rows as $row): $s=strtolower($row['status']);$cls=['new'=>'badge-new','confirmed'=>'badge-confirmed','in_progress'=>'badge-progress','completed'=>'badge-completed','cancelled'=>'badge-cancelled'][$s]??'badge-new';?><tr><td><strong><?=e($row['booking_number'])?></strong><div class="text-muted small"><?=e(date('d M Y, h:i A',strtotime($row['created_at'])))?></div></td><td><?=e($row['full_name'])?><div class="text-muted small"><?=e($row['mobile_number'])?></div></td><td class="route-cell"><strong><?=e($row['source_location'])?></strong><span>to <?=e($row['destination_location'])?></span></td><td><?=e(date('d M Y',strtotime($row['preferred_date'])))?></td><td><?=e(str_replace('_',' ',$row['trip_type']))?></td><td><?=e((string)$row['participants'])?></td><td><span class="badge <?=$cls?>"><?=e(str_replace('_',' ',$row['status']))?></span></td><td><a class="btn-admin btn-primary" href="booking-view.php?id=<?=e((string)$row['id'])?>">View</a></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php adminFooter(); ?>
